SELECT obj_perm_id, tenant_id, user_id, resource_type, resource_id, permissions, granted_by, created_at
FROM iam_object_permission
WHERE obj_perm_id = #{objPermId}

SELECT obj_perm_id, tenant_id, user_id, resource_type, resource_id, permissions, granted_by, created_at
FROM iam_object_permission
WHERE tenant_id = #{tenantId} AND user_id = #{userId}

SELECT obj_perm_id, tenant_id, user_id, resource_type, resource_id, permissions, granted_by, created_at
FROM iam_object_permission
WHERE tenant_id = #{tenantId}
